export const envelope = [25, 35, 25];

export default function build(api) {
  const { size } = api;
  const SY = 6; // seat plane at y = 6 to allow downward terrain conformity skirt

  // 1. Resolve World Palette from Theme
  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:mossy_stone_bricks";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";

  const groundPlinth = api.theme?.ground?.plinth || "minecraft:cobblestone";
  const groundRevetment = api.theme?.ground?.revetment || "minecraft:mossy_cobblestone";

  const roofSolid = api.theme?.roof?.solid || "minecraft:dark_oak_planks";
  const roofStairs = api.theme?.roof?.stairs || "minecraft:dark_oak_stairs";
  const roofSlab = api.theme?.roof?.slab || "minecraft:dark_oak_slab";

  // Helper block state builders
  function stairStr(base, facing, half = "bottom") {
    const id = base.split("[")[0];
    return `${id}[facing=${facing},half=${half}]`;
  }

  function slabStr(base, type = "bottom") {
    const id = base.split("[")[0];
    return `${id}[type=${type}]`;
  }

  function logStr(base, axis = "y") {
    const id = base.split("[")[0];
    return `${id}[axis=${axis}]`;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      api.set(x, y, z, block);
    }
  }

  // Deterministic masonry texture variation
  function getStone(x, y, z, accentRatio = 0.22) {
    let h = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453;
    let val = h - Math.floor(h);
    return val < accentRatio ? stoneAccent : stonePrimary;
  }

  // Turret geometry helpers
  const turretCenters = [
    { cx: 4, cz: 4 },   // NW
    { cx: 20, cz: 4 },  // NE
    { cx: 4, cz: 20 },  // SW
    { cx: 20, cz: 20 }, // SE
  ];

  function getTurretInfo(x, z) {
    for (const { cx, cz } of turretCenters) {
      const dx = x - cx;
      const dz = z - cz;
      const adx = Math.abs(dx);
      const adz = Math.abs(dz);
      if (adx <= 2 && adz <= 2 && !(adx === 2 && adz === 2)) {
        const isWall = (adx === 2 || adz === 2 || (adx === 1 && adz === 1));
        return { cx, cz, dx, dz, adx, adz, isWall, isInside: !isWall };
      }
    }
    return null;
  }

  function isKeepFootprint(x, z) {
    // Main central keep body
    if (x >= 4 && x <= 20 && z >= 4 && z <= 20) return true;
    // Four corner turrets
    if (getTurretInfo(x, z) !== null) return true;
    // North entrance ramp/stairs
    if (x >= 10 && x <= 14 && z >= 0 && z <= 3) return true;
    // Plinth talus flare
    if (x >= 3 && x <= 21 && z >= 3 && z <= 21) {
      if ((x === 3 || x === 21) && (z === 3 || z === 21)) return false;
      return true;
    }
    return false;
  }

  // --- 1. FOUNDATION & TERRAIN CONFORMITY (Rule 6) ---
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      if (!isKeepFootprint(x, z)) continue;

      const h = api.heightAt(x, z);
      const localGround = Math.max(0, Math.min(SY + 2, SY + h));

      // Build solid footing down to ground level
      for (let y = localGround; y <= SY; y++) {
        if (y < SY - 2) {
          setBlock(x, y, z, groundRevetment);
        } else if (y < SY) {
          setBlock(x, y, z, groundPlinth);
        } else {
          setBlock(x, y, z, getStone(x, y, z, 0.4));
        }
      }
    }
  }

  // --- 2. TALUS PLINTH & GROUND LEVEL (y = SY, SY + 1) ---
  // Outer battered base on ground course
  for (let x = 3; x <= 21; x++) {
    for (let z = 3; z <= 21; z++) {
      if ((x === 3 || x === 21) && (z === 3 || z === 21)) continue;

      if (x === 3 && z >= 6 && z <= 18) {
        setBlock(x, SY, z, stairStr(stoneStairs, "west"));
      } else if (x === 21 && z >= 6 && z <= 18) {
        setBlock(x, SY, z, stairStr(stoneStairs, "east"));
      } else if (z === 3 && x >= 6 && x <= 18 && (x < 10 || x > 14)) {
        setBlock(x, SY, z, stairStr(stoneStairs, "north"));
      } else if (z === 21 && x >= 6 && x <= 18) {
        setBlock(x, SY, z, stairStr(stoneStairs, "south"));
      }
    }
  }

  // Main ground floor slab at y = SY + 1
  for (let x = 4; x <= 20; x++) {
    for (let z = 4; z <= 20; z++) {
      setBlock(x, SY + 1, z, getStone(x, SY + 1, z, 0.15));
    }
  }
  // Floor inlay pattern in Great Hall
  for (let x = 7; x <= 17; x++) {
    for (let z = 7; z <= 17; z++) {
      if ((x + z) % 2 === 0) {
        setBlock(x, SY + 1, z, woodPlanks);
      } else {
        setBlock(x, SY + 1, z, stonePrimary);
      }
    }
  }

  // --- 3. NORTH ENTRANCE STAIRCASE & PORTAL ---
  // Steps rising to entrance
  for (let x = 11; x <= 13; x++) {
    setBlock(x, SY, 0, stairStr(stoneStairs, "north"));
    setBlock(x, SY, 1, stairStr(stoneStairs, "north"));
    setBlock(x, SY + 1, 1, stairStr(stoneStairs, "north"));
    setBlock(x, SY + 1, 2, stairStr(stoneStairs, "north"));
    setBlock(x, SY + 1, 3, stonePrimary);
  }
  // Flanking balustrades
  setBlock(10, SY + 1, 1, stoneWall);
  setBlock(14, SY + 1, 1, stoneWall);
  setBlock(10, SY + 2, 2, stoneWall);
  setBlock(14, SY + 2, 2, stoneWall);
  setBlock(10, SY + 2, 3, stoneWall);
  setBlock(14, SY + 2, 3, stoneWall);

  // Arched Entrance Gateway (z = 4, x = 10..14)
  for (let y = SY + 2; y <= SY + 5; y++) {
    setBlock(10, y, 4, getStone(10, y, 4));
    setBlock(14, y, 4, getStone(14, y, 4));
  }
  setBlock(11, SY + 4, 4, stairStr(stoneStairs, "east", "top"));
  setBlock(13, SY + 4, 4, stairStr(stoneStairs, "west", "top"));
  setBlock(12, SY + 4, 4, stoneAccent);
  setBlock(12, SY + 5, 4, stonePrimary);
  // Lantern / fence above entrance
  setBlock(12, SY + 3, 3, woodFence);

  // --- 4. LOWER KEEP WALLS & TOWERS (y = SY + 2 to SY + 12) ---
  for (let y = SY + 2; y <= SY + 12; y++) {
    // 4 Corner Turrets
    for (const { cx, cz } of turretCenters) {
      for (let dx = -2; dx <= 2; dx++) {
        for (let dz = -2; dz <= 2; dz++) {
          const adx = Math.abs(dx);
          const adz = Math.abs(dz);
          if (adx === 2 && adz === 2) continue; // cut corners

          const isWall = (adx === 2 || adz === 2 || (adx === 1 && adz === 1));
          const tx = cx + dx;
          const tz = cz + dz;

          if (isWall) {
            // Arrow slits on turrets at y = SY + 4 and SY + 10
            const isSlit = (y === SY + 4 || y === SY + 10) && (adx === 2 || adz === 2);
            if (isSlit && ((cx === 4 && dx === -2) || (cx === 20 && dx === 2) || (cz === 20 && dz === 2))) {
              setBlock(tx, y, tz, stoneWall);
            } else {
              setBlock(tx, y, tz, getStone(tx, y, tz));
            }
          }
        }
      }
    }

    // Main Curtain Walls between turrets
    for (let x = 6; x <= 18; x++) {
      // North Wall (skip entrance doorway at x=11..13 on lower floor)
      if (y > SY + 3 || x < 11 || x > 13) {
        setBlock(x, y, 4, getStone(x, y, 4));
        setBlock(x, y, 5, getStone(x, y, 5));
      }
      // South Wall
      setBlock(x, y, 19, getStone(x, y, 19));
      setBlock(x, y, 20, getStone(x, y, 20));
    }

    for (let z = 6; z <= 18; z++) {
      // West Wall
      setBlock(4, y, z, getStone(4, y, z));
      setBlock(5, y, z, getStone(5, y, z));
      // East Wall
      setBlock(19, y, z, getStone(19, y, z));
      setBlock(20, y, z, getStone(20, y, z));
    }

    // Arrow slits in lower curtain walls at y = SY + 4 and y = SY + 10
    if (y === SY + 4 || y === SY + 10) {
      // West wall embrasures
      setBlock(4, y, 10, stoneWall);
      setBlock(4, y, 14, stoneWall);
      // East wall embrasures
      setBlock(20, y, 10, stoneWall);
      setBlock(20, y, 14, stoneWall);
      // South wall embrasures
      setBlock(10, y, 20, stoneWall);
      setBlock(14, y, 20, stoneWall);
    }
  }

  // Four Grand Great Hall Pillars & Arch Vaults (y = SY + 2 to SY + 7)
  const pillars = [[9, 9], [15, 9], [9, 15], [15, 15]];
  for (const [px, pz] of pillars) {
    for (let y = SY + 2; y <= SY + 6; y++) {
      setBlock(px, y, pz, stonePrimary);
    }
    // Arch corbels at pillar capitals
    setBlock(px - 1, SY + 6, pz, stairStr(stoneStairs, "east", "top"));
    setBlock(px + 1, SY + 6, pz, stairStr(stoneStairs, "west", "top"));
    setBlock(px, SY + 6, pz - 1, stairStr(stoneStairs, "south", "top"));
    setBlock(px, SY + 6, pz + 1, stairStr(stoneStairs, "north", "top"));
  }

  // NW Turret Spiral Staircase (Connecting all levels from y = SY + 1 to SY + 26)
  for (let y = SY + 2; y <= SY + 26; y++) {
    setBlock(4, y, 4, stonePrimary); // central newel post
    const step = (y - SY) % 4;
    if (step === 0) setBlock(4, y, 3, stairStr(woodStairs, "east"));
    else if (step === 1) setBlock(5, y, 4, stairStr(woodStairs, "south"));
    else if (step === 2) setBlock(4, y, 5, stairStr(woodStairs, "west"));
    else setBlock(3, y, 4, stairStr(woodStairs, "north"));
  }

  // --- 5. MID FLOOR (Armory / Garrison Floor at y = SY + 7) ---
  for (let x = 6; x <= 18; x++) {
    for (let z = 6; z <= 18; z++) {
      if (x === 9 || x === 15 || z === 9 || z === 15) {
        setBlock(x, SY + 7, z, logStr(woodLog, x === 9 || x === 15 ? "z" : "x"));
      } else {
        setBlock(x, SY + 7, z, woodPlanks);
      }
    }
  }

  // Pillars continuing through Garrison floor
  for (const [px, pz] of pillars) {
    for (let y = SY + 8; y <= SY + 12; y++) {
      setBlock(px, y, pz, stonePrimary);
    }
    setBlock(px - 1, SY + 12, pz, stairStr(stoneStairs, "east", "top"));
    setBlock(px + 1, SY + 12, pz, stairStr(stoneStairs, "west", "top"));
    setBlock(px, SY + 12, pz - 1, stairStr(stoneStairs, "south", "top"));
    setBlock(px, SY + 12, pz + 1, stairStr(stoneStairs, "north", "top"));
  }

  // --- 6. LOWER MACHICOLATIONS & OUTER BATTLEMENTS (y = SY + 12 to SY + 15) ---
  // Machicolation Corbels under lower wall walk at y = SY + 12
  for (let x = 6; x <= 18; x++) {
    setBlock(x, SY + 12, 3, stairStr(stoneStairs, "south", "top"));
    setBlock(x, SY + 12, 21, stairStr(stoneStairs, "north", "top"));
  }
  for (let z = 6; z <= 18; z++) {
    setBlock(3, SY + 12, z, stairStr(stoneStairs, "east", "top"));
    setBlock(21, SY + 12, z, stairStr(stoneStairs, "west", "top"));
  }

  // Outer Battlement Walkway Floor at y = SY + 13
  for (let x = 3; x <= 21; x++) {
    for (let z = 3; z <= 21; z++) {
      if ((x >= 3 && x <= 5) || (x >= 19 && x <= 21) || (z >= 3 && z <= 5) || (z >= 19 && z <= 21)) {
        if (!((x < 6 || x > 18) && (z < 6 || z > 18))) {
          setBlock(x, SY + 13, z, stonePrimary);
        }
      }
    }
  }

  // Outer Merlons and Crenellations at y = SY + 14 and SY + 15
  for (let x = 3; x <= 21; x++) {
    if (x >= 6 && x <= 18) {
      // North parapet
      const isMerlon = (x % 2 === 0);
      setBlock(x, SY + 14, 3, isMerlon ? stonePrimary : stoneWall);
      if (isMerlon) setBlock(x, SY + 15, 3, slabStr(stoneSlab, "bottom"));

      // South parapet
      setBlock(x, SY + 14, 21, isMerlon ? stonePrimary : stoneWall);
      if (isMerlon) setBlock(x, SY + 15, 21, slabStr(stoneSlab, "bottom"));
    }
  }

  for (let z = 3; z <= 21; z++) {
    if (z >= 6 && z <= 18) {
      // West parapet
      const isMerlon = (z % 2 === 0);
      setBlock(3, SY + 14, z, isMerlon ? stonePrimary : stoneWall);
      if (isMerlon) setBlock(3, SY + 15, z, slabStr(stoneSlab, "bottom"));

      // East parapet
      setBlock(21, SY + 14, z, isMerlon ? stonePrimary : stoneWall);
      if (isMerlon) setBlock(21, SY + 15, z, slabStr(stoneSlab, "bottom"));
    }
  }

  // --- 7. UPPER KEEP / LORD'S SOLAR (y = SY + 13 to SY + 19) ---
  // Floor of Solar at y = SY + 13
  for (let x = 6; x <= 18; x++) {
    for (let z = 6; z <= 18; z++) {
      setBlock(x, SY + 13, z, (x + z) % 2 === 0 ? woodPlanks : stonePrimary);
    }
  }

  // Upper Keep Walls (x = 6, 18; z = 6, 18) from y = SY + 14 to SY + 19
  for (let y = SY + 14; y <= SY + 19; y++) {
    for (let x = 6; x <= 18; x++) {
      setBlock(x, y, 6, getStone(x, y, 6));
      setBlock(x, y, 18, getStone(x, y, 18));
    }
    for (let z = 6; z <= 18; z++) {
      setBlock(6, y, z, getStone(6, y, z));
      setBlock(18, y, z, getStone(18, y, z));
    }
  }

  // Grand Gothic Windows in Lord's Solar (N, S, E, W faces)
  // North Face (z = 6)
  setBlock(11, SY + 15, 6, stairStr(stoneStairs, "north"));
  setBlock(12, SY + 15, 6, stairStr(stoneStairs, "north"));
  setBlock(13, SY + 15, 6, stairStr(stoneStairs, "north"));
  setBlock(11, SY + 16, 6, woodFence);
  setBlock(12, SY + 16, 6, woodFence);
  setBlock(13, SY + 16, 6, woodFence);
  setBlock(11, SY + 17, 6, stairStr(stoneStairs, "east", "top"));
  setBlock(12, SY + 17, 6, stoneAccent);
  setBlock(13, SY + 17, 6, stairStr(stoneStairs, "west", "top"));

  // South Face (z = 18)
  setBlock(11, SY + 15, 18, stairStr(stoneStairs, "south"));
  setBlock(12, SY + 15, 18, stairStr(stoneStairs, "south"));
  setBlock(13, SY + 15, 18, stairStr(stoneStairs, "south"));
  setBlock(11, SY + 16, 18, woodFence);
  setBlock(12, SY + 16, 18, woodFence);
  setBlock(13, SY + 16, 18, woodFence);
  setBlock(11, SY + 17, 18, stairStr(stoneStairs, "east", "top"));
  setBlock(12, SY + 17, 18, stoneAccent);
  setBlock(13, SY + 17, 18, stairStr(stoneStairs, "west", "top"));

  // West Face (x = 6)
  setBlock(6, SY + 15, 11, stairStr(stoneStairs, "west"));
  setBlock(6, SY + 15, 12, stairStr(stoneStairs, "west"));
  setBlock(6, SY + 15, 13, stairStr(stoneStairs, "west"));
  setBlock(6, SY + 16, 11, woodFence);
  setBlock(6, SY + 16, 12, woodFence);
  setBlock(6, SY + 16, 13, woodFence);
  setBlock(6, SY + 17, 11, stairStr(stoneStairs, "south", "top"));
  setBlock(6, SY + 17, 12, stoneAccent);
  setBlock(6, SY + 17, 13, stairStr(stoneStairs, "north", "top"));

  // East Face (x = 18)
  setBlock(18, SY + 15, 11, stairStr(stoneStairs, "east"));
  setBlock(18, SY + 15, 12, stairStr(stoneStairs, "east"));
  setBlock(18, SY + 15, 13, stairStr(stoneStairs, "east"));
  setBlock(18, SY + 16, 11, woodFence);
  setBlock(18, SY + 16, 12, woodFence);
  setBlock(18, SY + 16, 13, woodFence);
  setBlock(18, SY + 17, 11, stairStr(stoneStairs, "south", "top"));
  setBlock(18, SY + 17, 12, stoneAccent);
  setBlock(18, SY + 17, 13, stairStr(stoneStairs, "north", "top"));

  // Solar Ceiling / Upper Keep Roof Platform at y = SY + 19
  for (let x = 6; x <= 18; x++) {
    for (let z = 6; z <= 18; z++) {
      setBlock(x, SY + 19, z, stonePrimary);
    }
  }

  // --- 8. FOUR CORNER TURRETS UPPER STAGES & CONICAL CAPS (y = SY + 13 to SY + 23) ---
  for (const { cx, cz } of turretCenters) {
    // Upper shaft of turrets from y = SY + 13 to SY + 19
    for (let y = SY + 13; y <= SY + 19; y++) {
      for (let dx = -2; dx <= 2; dx++) {
        for (let dz = -2; dz <= 2; dz++) {
          const adx = Math.abs(dx);
          const adz = Math.abs(dz);
          if (adx === 2 && adz === 2) continue;
          const isWall = (adx === 2 || adz === 2 || (adx === 1 && adz === 1));
          if (isWall) {
            setBlock(cx + dx, y, cz + dz, getStone(cx + dx, y, cz + dz));
          }
        }
      }
    }

    // Turret Corbeling at y = SY + 19
    for (let dx = -2; dx <= 2; dx++) {
      for (let dz = -2; dz <= 2; dz++) {
        const adx = Math.abs(dx);
        const adz = Math.abs(dz);
        if (adx === 2 && adz === 0) {
          setBlock(cx + dx, SY + 19, cz + dz, stairStr(stoneStairs, dx > 0 ? "west" : "east", "top"));
        } else if (adz === 2 && adx === 0) {
          setBlock(cx + dx, SY + 19, cz + dz, stairStr(stoneStairs, dz > 0 ? "north" : "south", "top"));
        }
      }
    }

    // Turret Platform at y = SY + 20
    for (let dx = -2; dx <= 2; dx++) {
      for (let dz = -2; dz <= 2; dz++) {
        const adx = Math.abs(dx);
        const adz = Math.abs(dz);
        if (adx === 2 && adz === 2) continue;
        setBlock(cx + dx, SY + 20, cz + dz, stonePrimary);
      }
    }

    // Conical Turret Roofs (y = SY + 21 to SY + 23)
    // Tier 1: Outer roof ring (y = SY + 21)
    for (let dx = -2; dx <= 2; dx++) {
      for (let dz = -2; dz <= 2; dz++) {
        const adx = Math.abs(dx);
        const adz = Math.abs(dz);
        if (adx === 2 && adz === 2) continue;

        if (adx === 2 && adz <= 1) {
          setBlock(cx + dx, SY + 21, cz + dz, stairStr(roofStairs, dx > 0 ? "west" : "east"));
        } else if (adz === 2 && adx <= 1) {
          setBlock(cx + dx, SY + 21, cz + dz, stairStr(roofStairs, dz > 0 ? "north" : "south"));
        } else if (adx === 1 && adz === 1) {
          setBlock(cx + dx, SY + 21, cz + dz, roofSolid);
        }
      }
    }

    // Tier 2: Mid roof ring (y = SY + 22)
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        if (dx === 0 && dz === 0) {
          setBlock(cx, SY + 22, cz, roofSolid);
        } else if (Math.abs(dx) === 1 && dz === 0) {
          setBlock(cx + dx, SY + 22, cz, stairStr(roofStairs, dx > 0 ? "west" : "east"));
        } else if (Math.abs(dz) === 1 && dx === 0) {
          setBlock(cx, SY + 22, cz + dz, stairStr(roofStairs, dz > 0 ? "north" : "south"));
        } else {
          setBlock(cx + dx, SY + 22, cz + dz, roofSolid);
        }
      }
    }

    // Tier 3: Roof Pinnacle Finial (y = SY + 23)
    setBlock(cx, SY + 23, cz, woodFence);
  }

  // --- 9. GRAND HIGH BATTLEMENTS & CROWN (y = SY + 19 to SY + 22) ---
  // Overhanging machicolation corbels at y = SY + 19 around upper keep
  for (let x = 5; x <= 19; x++) {
    setBlock(x, SY + 19, 5, stairStr(stoneStairs, "south", "top"));
    setBlock(x, SY + 19, 19, stairStr(stoneStairs, "north", "top"));
  }
  for (let z = 5; z <= 19; z++) {
    setBlock(5, SY + 19, z, stairStr(stoneStairs, "east", "top"));
    setBlock(19, SY + 19, z, stairStr(stoneStairs, "west", "top"));
  }

  // High Walk Platform at y = SY + 20
  for (let x = 5; x <= 19; x++) {
    for (let z = 5; z <= 19; z++) {
      setBlock(x, SY + 20, z, stonePrimary);
    }
  }

  // High Merlons & Crenellations at y = SY + 21 and SY + 22
  for (let x = 5; x <= 19; x++) {
    const isMerlon = (x % 2 === 1);
    // North Merlons
    setBlock(x, SY + 21, 5, isMerlon ? stonePrimary : stoneWall);
    if (isMerlon) setBlock(x, SY + 22, 5, slabStr(stoneSlab, "bottom"));

    // South Merlons
    setBlock(x, SY + 21, 19, isMerlon ? stonePrimary : stoneWall);
    if (isMerlon) setBlock(x, SY + 22, 19, slabStr(stoneSlab, "bottom"));
  }

  for (let z = 5; z <= 19; z++) {
    const isMerlon = (z % 2 === 1);
    // West Merlons
    setBlock(5, SY + 21, z, isMerlon ? stonePrimary : stoneWall);
    if (isMerlon) setBlock(5, SY + 22, z, slabStr(stoneSlab, "bottom"));

    // East Merlons
    setBlock(19, SY + 21, z, isMerlon ? stonePrimary : stoneWall);
    if (isMerlon) setBlock(19, SY + 22, z, slabStr(stoneSlab, "bottom"));
  }

  // Four High Corner Bartizans / Lookout posts at (5,5), (19,5), (5,19), (19,19)
  const highCorners = [[5, 5], [19, 5], [5, 19], [19, 19]];
  for (const [hx, hz] of highCorners) {
    setBlock(hx, SY + 21, hz, stonePrimary);
    setBlock(hx, SY + 22, hz, stoneWall);
    setBlock(hx, SY + 23, hz, woodFence);
  }

  // --- 10. CENTRAL SUMMIT WATCHTOWER & BELFRY (y = SY + 21 to SY + 27) ---
  // Corner pillars at (10, 10), (14, 10), (10, 14), (14, 14)
  for (const px of [10, 14]) {
    for (const pz of [10, 14]) {
      for (let y = SY + 21; y <= SY + 24; y++) {
        setBlock(px, y, pz, stonePrimary);
      }
    }
  }

  // Open observation arches on summit watchtower
  // Arch headers at y = SY + 23
  setBlock(11, SY + 23, 10, stairStr(stoneStairs, "east", "top"));
  setBlock(12, SY + 23, 10, stoneAccent);
  setBlock(13, SY + 23, 10, stairStr(stoneStairs, "west", "top"));

  setBlock(11, SY + 23, 14, stairStr(stoneStairs, "east", "top"));
  setBlock(12, SY + 23, 14, stoneAccent);
  setBlock(13, SY + 23, 14, stairStr(stoneStairs, "west", "top"));

  setBlock(10, SY + 23, 11, stairStr(stoneStairs, "south", "top"));
  setBlock(10, SY + 23, 12, stoneAccent);
  setBlock(10, SY + 23, 13, stairStr(stoneStairs, "north", "top"));

  setBlock(14, SY + 23, 11, stairStr(stoneStairs, "south", "top"));
  setBlock(14, SY + 23, 12, stoneAccent);
  setBlock(14, SY + 23, 13, stairStr(stoneStairs, "north", "top"));

  // Watchtower Grand Timber/Slate Hipped Roof (y = SY + 24 to SY + 27)
  // Tier 1: Overhanging Eaves (7x7 at y = SY + 24)
  for (let x = 9; x <= 15; x++) {
    setBlock(x, SY + 24, 9, stairStr(roofStairs, "south"));
    setBlock(x, SY + 24, 15, stairStr(roofStairs, "north"));
  }
  for (let z = 9; z <= 15; z++) {
    setBlock(9, SY + 24, z, stairStr(roofStairs, "east"));
    setBlock(15, SY + 24, z, stairStr(roofStairs, "west"));
  }
  for (let x = 10; x <= 14; x++) {
    for (let z = 10; z <= 14; z++) {
      setBlock(x, SY + 24, z, roofSolid);
    }
  }

  // Tier 2: Mid Sloping Roof (5x5 at y = SY + 25)
  for (let x = 10; x <= 14; x++) {
    setBlock(x, SY + 25, 10, stairStr(roofStairs, "south"));
    setBlock(x, SY + 25, 14, stairStr(roofStairs, "north"));
  }
  for (let z = 10; z <= 14; z++) {
    setBlock(10, SY + 25, z, stairStr(roofStairs, "east"));
    setBlock(14, SY + 25, z, stairStr(roofStairs, "west"));
  }
  for (let x = 11; x <= 13; x++) {
    for (let z = 11; z <= 13; z++) {
      setBlock(x, SY + 25, z, roofSolid);
    }
  }

  // Tier 3: Roof Ridge Crown (3x3 at y = SY + 26)
  for (let x = 11; x <= 13; x++) {
    for (let z = 11; z <= 13; z++) {
      if (x === 12 && z === 12) {
        setBlock(x, SY + 26, z, roofSolid);
      } else {
        setBlock(x, SY + 26, z, slabStr(roofSlab, "bottom"));
      }
    }
  }

  // Tier 4: Summit Spire Pinnacle (y = SY + 27)
  setBlock(12, SY + 27, 12, woodFence);

  return {
    name: "hilltop_castle_keep",
    seatY: SY,
    anchors: {
      front: [12, SY, 0],
      door: [12, SY + 1, 3],
      keep_summit: [12, SY + 27, 12],
    },
    interiors: [
      {
        min: [7, SY + 2, 7],
        max: [17, SY + 6, 17],
        kind: "hall",
      },
      {
        min: [7, SY + 8, 7],
        max: [17, SY + 12, 17],
        kind: "quarters",
      },
      {
        min: [8, SY + 14, 8],
        max: [16, SY + 18, 16],
        kind: "vault",
      },
      {
        min: [11, SY + 21, 11],
        max: [13, SY + 23, 13],
        kind: "bridge",
      },
    ],
  };
}
